
import json
from pathlib import Path

from flask import Flask, jsonify, render_template
from detection import detect_repeated_failed_logins

app = Flask(__name__)

@app.route("/api/alerts")
def get_alerts():
    """Return alerts generated by our detection engine."""
    events = load_events()
    alerts = detect_repeated_failed_logins(events)

    return jsonify(alerts)


BASE_DIR = Path(__file__).resolve().parent
EVENTS_FILE = BASE_DIR / "data" / "sample_events.json"


def load_events():
    """Load our fictional security events."""
    with EVENTS_FILE.open("r", encoding="utf-8") as file:
        return json.load(file)


@app.route("/")
def home():
    """Display the dashboard homepage."""
    return render_template("index.html")


@app.route("/api/events")
def get_events():
    """Return all sample events as JSON."""
    return jsonify(load_events())


@app.route("/api/summary")
def get_summary():
    """Calculate basic security-event statistics."""
    events = load_events()

    summary = {
        "total_events": len(events),
        "high_severity": sum(
            event["severity"] == "high" for event in events
        ),
        "medium_severity": sum(
            event["severity"] == "medium" for event in events
        ),
        "low_severity": sum(
            event["severity"] == "low" for event in events
        ),
    }

    return jsonify(summary)


if __name__ == "__main__":
    app.run(debug=True)
